@namespace sv_8fbc0aa4a155448e991c5e7a2ffee2da.Components.Pages.Apply

<div class="d-flex justify-content-between align-items-center mb-4 position-relative">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var isCompleted = stepIndex < CurrentStep;
        var isCurrent = stepIndex == CurrentStep;
        var isFuture = stepIndex > CurrentStep;

        <div class="text-center flex-fill position-relative" style="z-index: 1;">
            <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepButtonClass(isCompleted, isCurrent)"
                    style="width: 40px; height: 40px; font-size: 0.85rem;"
                    disabled="@isFuture"
                    @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                @if (isCompleted)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </button>
            <div class="small mt-1 @(isFuture ? "text-muted" : (isCurrent ? "fw-bold" : ""))">
                @StepNames[stepIndex]
            </div>
        </div>

        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="flex-fill d-flex align-items-center" style="margin-top: -1.2rem;">
                <hr class="w-100 @(stepIndex < CurrentStep ? "border-primary" : "border-secondary")" />
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private static string StepButtonClass(bool completed, bool current) => (completed, current) switch
    {
        (true, _) => "btn-success text-white",
        (_, true) => "btn-primary text-white",
        _ => "btn-outline-secondary"
    };
}

@namespace sv_8fbc0aa4a155448e991c5e7a2ffee2da.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @Index</h6>
            @if (ShowRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input class="form-control" value="@Company" @onchange="e => Update(company: e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input class="form-control" value="@Title" @onchange="e => Update(title: e.Value?.ToString())" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@FormatDate(StartDate)" @onchange="e => OnStartDateChange(e)" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@FormatDate(EndDate)" disabled="@IsCurrent"
                       @onchange="e => OnEndDateChange(e)" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" checked="@IsCurrent"
                           @onchange="e => OnCurrentToggle((bool)(e.Value ?? false))" />
                    <label class="form-check-label">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Description"
                          @onchange="e => Update(description: e.Value?.ToString())"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public string Description { get; set; } = "";
