                   Name="@r.Name"
                   Relationship="@r.Relationship"
                   Email="@r.Email"
                   Phone="@r.Phone"
                   ShowRemove="@(References.Count > 2)"
                   OnRemove="() => RemoveReference(idx)"
                   OnChanged="data => UpdateReference(idx, data)" />
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
