    <textarea class="form-control" rows="12" maxlength="@MaxLength"
              value="@CoverLetter"
              @onchange="e => { CoverLetter = e.Value?.ToString() ?? ""; }"
              @oninput="e => { CoverLetter = e.Value?.ToString() ?? ""; }"
              placeholder="Write your cover letter here..."></textarea>
    <div class="text-muted text-end mt-1">
        @CoverLetter.Length / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">&larr; Back</button>
