@page "/apply"
@namespace sv_8fbc0aa4a155448e991c5e7a2ffee2da.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_8fbc0aa4a155448e991c5e7a2ffee2da.Models

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h3 class="mb-4 text-center">Job Application</h3>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@personalResult!"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnBack="GoBack"
                        OnEditSection="GoToStep"
                        OnSubmit="HandleSubmit"
                        IsSubmitting="@isSubmitting"
                        Submitted="@submitted"
                        ApplicationId="@applicationId"
                        ErrorMessage="@submitError" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep;

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";
    private PersonalInfoStep.PersonalInfoResult? personalResult;

    // Step 2 state
    private List<WorkHistoryStep.EntryModel> workEntries = new();

    // Step 3 state
    private List<ReferencesStep.RefModel> references = new();

    // Step 4 state
    private string coverLetter = "";

    // Step 5 state
    private bool isSubmitting;
    private bool submitted;
    private int applicationId;
    private string? submitError;

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalResult = result;
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.RefModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private void GoBack() => currentStep = Math.Max(0, currentStep - 1);

    private void GoToStep(int step)
    {
        // Only allow navigation to completed steps (before current) or current
        if (step <= currentStep)
            currentStep = step;
    }

    private async Task HandleSubmit()
    {
        if (personalResult is null) return;

        isSubmitting = true;
        submitError = null;

        try
        {
            var workHistory = new WorkHistory(
                workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.EndDate, e.Description
                )).ToList()
            );

            var refList = references.Select(r => new Reference(
                r.Name, r.Relationship, r.Email, r.Phone
            )).ToList();

            var application = new JobApplication(
                new PersonalInfo(personalResult.FullName, personalResult.Email,
                                 personalResult.Phone, personalResult.Address),
                workHistory, refList, coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            submitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

@page "/apply"
@namespace sv_8fbc0aa4a155448e991c5e7a2ffee2da.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_8fbc0aa4a155448e991c5e7a2ffee2da.Models

